    ('fvg', '// fvg — fair value gaps (three-bar imbalance).\n//\n// `min_size` is what makes ONE predicate serve both migration targets:\n//\n//   fvg.up(0)                     Super OrderBlock — the strict Pine form\n//   fvg.up(ta.atr(14) * sens)     ICT Suite — the ATR-filtered form\n//\n// `min_size = 0` is exactly the unfiltered test, because the gap is already\n// strictly positive when the first conjunct holds: `low > high[2]` implies\n// `low - high[2] > 0`. So the second conjunct is a no-op at 0 rather than an\n// off-by-one, and a caller who wants "no filter" does NOT need a separate\n// function.\n//\n// GEOMETRY. The gap\'s own edges are the box: for a bullish gap the top is this\n// bar\'s low and the bottom is the high two bars back. That makes an FVG zone\n// structurally immune to spawn-bar self-mitigation (design note N1) — its edges\n// ARE the bar\'s own extremes, so the spawn bar cannot straddle them.\n\nup(min_size) => low > high[2] and (low - high[2]) > min_size\ndown(min_size) => high < low[2] and (low[2] - high) > min_size\n\nup_top() => low\nup_bottom() => high[2]\nup_mid() => (low + high[2]) / 2\n\ndown_top() => low[2]\ndown_bottom() => high\ndown_mid() => (high + low[2]) / 2\n'),
    ('ob', "// ob — order blocks (engulfing reversal against the prior candle).\n//\n// A bullish OB is a down candle followed by an up candle that closes beyond the\n// down candle's high. Pine writes this as `isObUp(index)` over a parameterized\n// history index; that form is NOT expressible here (a history offset must be a\n// literal — design §5), so these are 0-anchored and the caller shifts:\n//\n//   Pine  isObUp(1)   ->   ob.up()[1]\n//\n// GEOMETRY, and the asymmetry is deliberate, not a typo. The bullish box runs\n// from the trapped candle's high down to the LOWER of the two lows; the bearish\n// box runs from the HIGHER of the two highs down to the trapped candle's low.\n// Both are 0-anchored, so under `[1]` they reproduce Pine's `high[2]` /\n// `math.min(low[2], low[1])` pair exactly.\n\nup() => candle.down()[1] and candle.up() and close > high[1]\ndown() => candle.up()[1] and candle.down() and close < low[1]\n\nup_top() => high[1]\nup_bottom() => math.min(low[1], low)\n\ndown_top() => math.max(high[1], high)\ndown_bottom() => low[1]\n"),
